// Unsigned arbitrary-precision integers represented as strings of decimal digits.
//
// Canonical form: either "0" or a non-empty digit string with no leading zero.
// Everything here is deliberately tiny and side-effect free so it can be unit
// tested in isolation. No language-level wide-integer type is used anywhere.

/** Strip leading zeros; "" and "000" both become "0". */
export function normalize(a) {
  let i = 0;
  while (i < a.length - 1 && a.charCodeAt(i) === 48) i++;
  const s = a.slice(i);
  return s === '' ? '0' : s;
}

export function isZero(a) {
  return a === '0';
}

/** -1, 0 or 1 for a<b, a==b, a>b. Both operands must be canonical. */
export function compare(a, b) {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

/** a - b, requiring a >= b. */
export function subtract(a, b) {
  const out = new Array(a.length);
  let borrow = 0;
  for (let i = a.length - 1, j = b.length - 1; i >= 0; i--, j--) {
    let d = a.charCodeAt(i) - 48 - borrow - (j >= 0 ? b.charCodeAt(j) - 48 : 0);
    if (d < 0) {
      d += 10;
      borrow = 1;
    } else borrow = 0;
    out[i] = d;
  }
  return normalize(out.join(''));
}

/** a + 1. */
export function increment(a) {
  const out = a.split('');
  let i = out.length - 1;
  for (; i >= 0; i--) {
    if (out[i] === '9') out[i] = '0';
    else {
      out[i] = String.fromCharCode(out[i].charCodeAt(0) + 1);
      return out.join('');
    }
  }
  return '1' + out.join('');
}

