// child_process.spawn throw before either program runs).
import { readFileSync } from 'node:fs';
import { spawn } from 'node:child_process';

const EXE = '/workspace/dataset/test6_executable';
const entry = process.argv[2];
const tag = process.argv[3] || '';
let cases = readFileSync('/tmp/dt/corpus.jsonl', 'utf8').trim().split('\n').map((l) => JSON.parse(l));
cases = cases.map((c, i) => ({ ...c, i })).filter((c) => c.tag.startsWith(tag));

function run(cmd, args) {
  return new Promise((resolve) => {
    let p;
    try { p = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] }); }
    catch (e) { return resolve({ rc: -2, so: '', se: 'SPAWN-REFUSED' }); }
    let so = '', se = '';
    p.stdout.on('data', (d) => { so += d; });
    p.stderr.on('data', (d) => { se += d; });
    p.on('error', () => resolve({ rc: -1, so: '', se: 'SPAWN-ERROR' }));
    p.on('close', (rc) => resolve({ rc, so, se }));
  });
}
const normErr = (s) => s.replace(/\[PYI-\d+:ERROR\][^\n]*\n?/g, '').replace(/test6(_executable|\.py|\.mjs)/g, 'PROG').trim();

