  if (a.rc === -2 || b.rc === -2) { skipped++; console.log(`SKIP(unspawnable) #${c.i} ${JSON.stringify(c.argv)}`); continue; }
  let bad = null;
  if (a.so !== b.so) bad = 'stdout';
  else if (a.rc !== b.rc) bad = 'rc';
  else if (normErr(a.se) !== normErr(b.se)) bad = 'stderr';
  if (bad) { fail++; console.log(`FAIL[${bad}] #${c.i} ${JSON.stringify(c.argv)}\n  py ${a.rc} ${JSON.stringify(a.so)} ${JSON.stringify(normErr(a.se))}\n  js ${b.rc} ${JSON.stringify(b.so)} ${JSON.stringify(normErr(b.se))}`); }
  else ok++;
}
